{ 

    using (DataBase database = new DataBase(_context))
    {
        Views myView = _context.Views.SingleOrDefault(a => a.Id.ToString().ToLower() == ViewId.ToLower());
        if (myView == null)
        {
            myView = _context.Views.SingleOrDefault(a => a.DisplayName == ViewId);
        }
        //select the view by view Id

        if (myView != null)
        {
            List<DataSourceFields> fields = _context.DataSourceFields.Where(a => a.DataSourceId == myView.DataSourceId).ToList();
            if (fields.Count > 0)
            {
                string select = "", where = "", groupby = "", from = "",having="";
                List<Entities> currEntities = new List<Entities>();
                List<SqlParameter> parameters = new List<SqlParameter>();

                for (var i = 0; i < fields.Count; i++)
                {
                    DataSourceFields field = fields[i];
                    Fields myfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == field.FieldId);
                    Entities myentity = currEntities.FirstOrDefault(a => a.Id.ToString().ToLower() == field.EntityId.ToLower());
                    if (myentity == null)
                    {
                        myentity = _context.Entities.FirstOrDefault(a => a.Id.ToString() == field.EntityId);
                        currEntities.Add(myentity);
                    }
                    if (myfield != null && myentity != null)
                        AddToSelect(ref select, ref where, ref groupby, ref having, parameters, field, myfield, myentity);

                }

                if (currEntities.Count > 1)
                {
                    from = CreateJoinString(fields, from, currEntities);
                }
                else
                {
                    Entities myentity = currEntities[0];
                    from += "[dbo].[" + myentity.SysName + "] as [" + myentity.DisplayName + "] ";
                }
                if (select != "")
                {
                    select = "SELECT " + select;
                }
                if (from != "")
                {
                    from = " FROM " + from;
                }
                if (where != "")
                {
                    where = " WHERE " + where;
                }
                if (groupby != "")
                {
                    groupby = " GROUP BY " + groupby;
                    if(having!="")
                    {
                        having = " HAVING " + having;
                    }
                }
                if (select != "" && from != "")
                {
                    string sql = select + from + where + groupby + having;
                    return database.GetData(sql, parameters.ToArray());
                }
            }
        }

    }
    return new List<dynamic>();
}

{
    for (var i = 1; i < currEntities.Count; i++)
    {
        Entities prevEntity = currEntities[i - 1];
        Entities myentity = currEntities[i];

        List<DataSourceFields> prevjoinfields = fields.Where(a => a.JoinEntityId.ToLower() == prevEntity.Id.ToString().ToLower()).ToList();
        List<DataSourceFields> joinfields = fields.Where(a => a.JoinEntityId.ToLower() == myentity.Id.ToString().ToLower()).ToList();

        if (joinfields.Count > 0 && prevjoinfields.Count > 0)
        {
            if (from != "")
                from += " INNER JOIN ";
            else
                from += "[dbo].[" + prevEntity.SysName + "] as [" + prevEntity.DisplayName + "] INNER JOIN ";
            from += "[dbo].[" + myentity.SysName + "] as [" + myentity.DisplayName + "] ON ";
            bool and = false;
            for (var j = 0; j < joinfields.Count; j++)
            {
                DataSourceFields joinfield = joinfields[j];
                Fields myfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == joinfield.FieldId);
                string field1 = "[dbo].[" + myentity.SysName + "].[" + myfield.SystemName + "] ";
                string jointype = joinfield.JoinType;
                if (joinfield.JoinCastType != "" && joinfield.JoinCastType != "null")
                {
                    field1 = "(" + field1 + " as " + joinfield.JoinCastType + " ) ";
                }
                DataSourceFields prevjoin = prevjoinfields.Where(a => a.JoinFieldId.ToLower() == joinfield.Id.ToString().ToLower()).FirstOrDefault();
                Fields myprevfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == prevjoin.FieldId);
                if (prevjoin == null)
                {
                    prevjoin = prevjoinfields.Where(a => a.JoinFieldId2.ToLower() == joinfield.Id.ToString().ToLower()).FirstOrDefault();
                    jointype = joinfield.JoinType2;
                    myprevfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == prevjoin.FieldId);
                    if (joinfield.JoinCastType2 != "" && joinfield.JoinCastType2 != "null")
                    {
                        field1 = "(" + field1 + " as " + joinfield.JoinCastType2 + " ) ";
                    }
                }
                string field2 = "[dbo].[" + prevEntity.SysName + "].[" + myprevfield.SystemName + "] ";

                if (prevjoin.JoinEntityId == myentity.Id.ToString().ToLower())
                {
                    if (prevjoin.JoinCastType != "" && prevjoin.JoinCastType != null)
                    {
                        field2 += "(" + field2 + " as " + prevjoin.JoinCastType + " ) ";
                    }

                }
                if (prevjoin.JoinEntityId2 == myentity.Id.ToString().ToLower())
                {
                    if (prevjoin.JoinCastType2 != "" && prevjoin.JoinCastType2 != null)
                    {
                        field2 += "(" + field2 + " as " + prevjoin.JoinCastType2 + " ) ";
                    }

                }
                if (and)
                    from += " AND ";
                and = true;
                from += field1 + jointype + field2;

            }
        }
        else
        {
            if (from != "")
                from += " AND ";
            else
                from += "[dbo].[" + prevEntity.SysName + "] as [" + prevEntity.DisplayName + "] AND ";
            from += "[dbo].[" + myentity.SysName + "] as [" + myentity.DisplayName + "]";
        }
    }

    return from;
}

