    ISearchResponse<object> response = Client.Search<object>(searchDescriptor);
    if (response.Hits.Count > 0)
    {
        Type type = typeof(T);
        ConstructorInfo ctor = type.GetConstructor(new[] { typeof(object) });
        List<T> resList = new List<T>();
        foreach (var hit in response.Hits)
        {
            T instance = ctor.Invoke(new object[] { hit.Source }) as T;
            resList.Add(instance);
        }
        return resList;
    }
    return new List<T>();
}

{
